package org.jsoup.nodes;

import org.jsoup.helper.Validate;
import org.jsoup.helper.StringUtil;

/**
 * A {@code <!DOCTYPE>} node.
 */
public class DocumentType extends Node {
    // todo: quirk mode from publicId and systemId

    /**
     * Constructs a doctype node.
     * @param name the name of the doctype
     * @param publicId the public identifier of the doctype
     * @param systemId the system identifier of the doctype
     * @param baseUri the base URI of the doctype
     */
    public DocumentType(String name, String publicId, String systemId, String baseUri) {
        super(baseUri);

        Validate.notEmpty(name);
        attr("name", name);
        attr("publicId", publicId);
        attr("systemId", systemId);
    }

    @Override
    public String nodeName() {
        return "#doctype";
    }

    @Override
    void outerHtmlHead(StringBuilder accum, int depth, Document.OutputSettings out) {
        String nameAttr = attr("name");
        String pubId = attr("publicId");
        String sysId = attr("systemId");

        accum.append("<!DOCTYPE");
        if (StringUtil.isBlank(nameAttr) == false)
            accum.append(" ").append(nameAttr);
        if (!StringUtil.isBlank(pubId))
            accum.append(" PUBLIC \"").append(pubId).append('"');
        if (!StringUtil.isBlank(sysId))
            accum.append(" \"").append(sysId).append('"');
        accum.append('>');
    }

    @Override
    void outerHtmlTail(StringBuilder accum, int depth, Document.OutputSettings out) {
        // no tail output for doctype
    }
}
